		/** 
		 * Tests creating a new Certification.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Certification");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Certification" );

			try {            
				Certification entity = CertificationService.getCertificationInstance().createCertification( generateNewEntity() );
				thePrimaryKey = entity.getCertificationId();
				LOGGER.info( "-- Successfully created a Certification with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Certification. 
		 */
		public Certification testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Certification" );

			Certification entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Certification with primary key" );
			msg.append( thePrimaryKey );
			
			CertificationFetchOneSummary fetchOneSummary = new CertificationFetchOneSummary( thePrimaryKey );

			try {
				entity = CertificationService.getCertificationInstance().getCertification( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Certification " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Certification.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Certification." );

			StringBuilder msg = new StringBuilder( "Failed to update a Certification : " );        
			Certification entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Certification." );

				// for use later on...
				thePrimaryKey = entity.getCertificationId();

				CertificationService proxy = CertificationService.getCertificationInstance();            
				proxy.updateCertification( entity );   

				LOGGER.info( "-- Successfully saved Certification - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Certification.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Certification." );

			try{
			    Certification entity = testRead(); 
				CertificationService.getCertificationInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Certification with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Certification with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Certifications.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Certifications:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Certification : " );        
			List<Certification> collection  = null;

			try {
				// call the static get method on the CertificationService
				collection = CertificationService.getCertificationInstance().getAllCertification();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Certification entity = null;            
					Iterator<Certification> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getCertificationId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

